from pathlib import Path
from lupa.lua51 import LuaRuntime

ROOT = Path(__file__).resolve().parents[1]
ADDON = ROOT / 'addon' / 'EmberLedgerForever'
passed = []

def test(name, body):
    lua = LuaRuntime(unpack_returned_tuples=True)
    lua.execute((ROOT / 'tests/mock.lua').read_text(encoding='utf-8'))
    ns = lua.table()
    for path in ['Ledger.lua', 'Loot.lua', 'Core.lua', 'Theme.lua', 'UI.lua', 'Options.lua', 'History.lua', 'Broker.lua']:
        lua.execute((ADDON / path).read_text(encoding='utf-8'), 'EmberLedgerForever', ns)
    lua.execute("E=EmberLedgerForever; E:OnEvent('ADDON_LOADED','EmberLedgerForever')")
    lua.execute(body)
    passed.append(name)
    print('PASS', name)

test('Small window initializes before login event', "assert(E.window:IsShown()); assert(E.db.session.state=='idle'); assert(E.visibleRows==3); assert(E.window.width==350 and E.window.height==206)")
test('All loot types and copper precision', "E:Start(); loot(1,3,1); loot(2,1,2); loot(3,1,3); money('You loot 1 Copper',4); assert(E.db.session.count==5); assert(E:Totals(E.db.session)==125); assert(E.db.session.coin==1)")
test('Duplicate line suppressed but repeated identical loot counted', "E:Start(); loot(1,2,10); loot(1,2,10); loot(1,2,11); assert(E.db.session.count==4)")
test('No line ID does not discard identical acquisitions', "E:Start(); loot(1,1); loot(1,1); assert(E.db.session.count==2)")
test('Other player and crafted messages excluded', "E:Start(); E:OnEvent('CHAT_MSG_LOOT','Other receives loot: '..link(1)..'.'); E:OnEvent('CHAT_MSG_LOOT','You create: '..link(1)..'.'); assert(E.db.session.count==0)")
test('Transfers and vendor transactions excluded', "E:Start(); for _,name in ipairs({'MerchantFrame','MailFrame','BankFrame','BankPanel','GuildBankFrame','TradeFrame','AuctionHouseFrame','AuctionFrame'}) do _G[name]=CreateFrame('Frame'); loot(1,1); money('You loot 3 Gold'); _G[name]:Hide() end; assert(E.db.session.count==0 and E.db.session.coin==0)")
test('Sales and wallet changes cannot double-count loot', "E:Start(); loot(2,1,1); E:OnEvent('PLAYER_MONEY'); E:OnEvent('BAG_UPDATE_DELAYED'); assert(E:Totals(E.db.session)==103); assert(not E.events.registered.PLAYER_MONEY)")
test('Coin components and guild deposit exclusion', "E:Start(); money('You loot 1 Gold, 2 Silver, 3 Copper (9 Gold deposited to guild bank)',1); money('Your share of the loot is 7 Copper.',2); assert(E.db.session.coin==10210)")
test('Coin duplicate suppression', "E:Start(); money('You loot 1 Copper',5); money('You loot 1 Copper',5); assert(E.db.session.coin==1)")
test('Pause excludes time and gains', "E:Start(); advance(60); E:Pause(); advance(900); loot(1,1); money('You loot 1 Gold'); assert(E.db.session.elapsed==60 and E.db.session.count==0 and E.db.session.coin==0); E:Start(); advance(60); loot(1,1); assert(E.db.session.elapsed==120); local _,rate=E:Totals(E.db.session); assert(rate==210)")
test('Finish snapshots history and is idempotent', "E:Start(); loot(1,1); advance(60); E:Finish(); E:Finish(); assert(#E.db.history==1); E:SetPrice(1,900); assert(E.db.history[1].items['item:1:0'].unit==7); assert(E.db.session.items['item:1:0'].unit==7)")
test('New session archives without destroying current results', "E:Start(); loot(1,2); E:New(); assert(#E.db.history==1 and E.db.history[1].count==2); assert(E.db.session.state=='idle' and E.db.session.count==0)")
test('History bounded and empty sessions omitted', "for i=1,25 do E:Start(); loot(1,1); E:New() end; assert(#E.db.history==20); E:Start(); E:New(); assert(#E.db.history==20)")
test('Manual price changes active rows and vendor reset works', "E:Start(); loot(1,2); E:SetPrice(1,10001); assert(E:Totals(E.db.session)==20002); E:SetPrice(1,nil); assert(E:Totals(E.db.session)==14)")
test('Uncached items retain quantities and resolve once', "E:Start(); loot(99,3); local _,_,u=E:Totals(E.db.session); assert(u==3 and requested[99]); catalog[99]={name='Loaded',price=1}; E:OnEvent('GET_ITEM_INFO_RECEIVED',99,true); E:OnEvent('GET_ITEM_INFO_RECEIVED',99,true); assert(E:Totals(E.db.session)==3 and E.db.session.count==3)")
test('Manual price survives delayed item metadata', "E:SetPrice(99,10); E:Start(); loot(99,2); catalog[99]={name='Loaded',price=1}; E:OnEvent('GET_ITEM_INFO_RECEIVED',99,true); local r=E.db.session.items['item:99:0']; assert(r.name=='Loaded' and r.unit==10)")
test('Finished unpriced history stays frozen', "E:Start(); loot(99,1); E:Finish(); catalog[99]={name='Loaded',price=10}; E:OnEvent('GET_ITEM_INFO_RECEIVED',99,true); local _,_,u=E:Totals(E.db.history[1]); assert(u==1)")
test('Reload resumes paused and excludes offline time', "E:Start(); loot(1,1); advance(50); E:OnEvent('PLAYER_LOGOUT'); now=9000; E:InitDB(); assert(E.db.session.state=='paused' and E.db.session.elapsed==50); advance(100); assert(E.db.session.elapsed==50)")
test('Malformed current data recovers', "EmberLedgerForeverDB={session={items={bad='x'},elapsed='no',coin=-4,state='weird'},prices={[1]='bad'},history={'bad'},scale=4}; E:InitDB(); assert(E.db.session.coin==0 and E.db.session.elapsed==0 and E.db.session.state=='paused'); assert(not next(E.db.session.items) and #E.db.history==0 and E.db.prices[1]==nil and E.db.scale==1.5)")
test('Localized and positional loot patterns', "LOOT_ITEM_SELF_MULTIPLE='Objets : %2$dx %1$s !'; E:BuildPatterns(); E:Start(); E:OnEvent('CHAT_MSG_LOOT','Objets : 3x '..link(1)..' !'); assert(E.db.session.count==3)")
test('Localized money patterns', "YOU_LOOT_MONEY='Vous recevez %s.'; GOLD_AMOUNT='%d or'; SILVER_AMOUNT='%d argent'; COPPER_AMOUNT='%d cuivre'; E:BuildPatterns(); E:Start(); money('Vous recevez 2 or, 3 argent, 4 cuivre.'); assert(E.db.session.coin==20304)")
test('Secret chat payloads fail closed', "E:Start(); E:OnEvent('CHAT_MSG_LOOT',{secret=true}); E:OnEvent('CHAT_MSG_MONEY',{secret=true}); assert(E.db.session.count==0 and E.db.session.coin==0)")
test('Zero elapsed and currency formatting', "assert(E:Totals(E.db.session)==0); local _,rate=E:Totals(E.db.session); assert(rate==0); assert(E.Money(1)=='1c' and E.Money(101)=='1s 01c' and E.Money(10001)=='1g 00s 01c')")
test('One-window controls, history and inline pricing', "E:ToggleOptions(); E.startButton.scripts.OnClick(); loot(1,1); E.rows[1].scripts.OnClick(); assert(E.editor:IsShown()); E:Finish(); E:ToggleHistory(); E:Refresh(); assert(not E.status.text:find('History')); assert(E.historyPanel:IsShown()); assert(not E.startButton.enabled)")
test('Pagination and hidden tracking', "E:Start(); for i=10,35 do catalog[i]={name='Item '..i,price=i}; loot(i,1) end; E.window.scripts.OnMouseWheel(nil,-1); assert(E.offset==3); E.window:Hide(); advance(5); loot(1,1); assert(E.db.session.count==27); SlashCmdList.EMBERLEDGERFOREVER(''); assert(E.window:IsShown()); assert(E.rowCount==27)")
test('No secure controls or launcher globals', "for _,f in ipairs(frames) do assert(not f.template or not f.template:find('Secure')) end; assert(not E.launcher and not E.minimap)")
test('Hidden bank child does not suppress skinning chat', "local hidden=CreateFrame('Frame'); hidden:Hide(); BankPanel=CreateFrame('Frame',nil,hidden); assert(BankPanel:IsShown() and not BankPanel:IsVisible()); E:Start(); loot(1,2,1); assert(E.db.session.count==2)")
test('Login automatically starts and archives prior work', "E:Start(); loot(1,2); E:OnEvent('PLAYER_ENTERING_WORLD',true,false); assert(E.db.session.state=='running' and E.db.session.count==0 and #E.db.history==1); loot(1,1); E:OnEvent('PLAYER_ENTERING_WORLD',false,false); assert(E.db.session.count==1)")
test('Reload preserves running intent without offline time', "E:Start(); advance(20); loot(1,1); E:OnEvent('PLAYER_LOGOUT'); now=9999; E:InitDB(); E:OnEvent('PLAYER_ENTERING_WORLD',false,true); assert(E.db.session.state=='running' and E.db.session.elapsed==20 and E.db.session.count==1)")
test('Reload preserves explicit pause', "E:Start(); E:Pause(); E:OnEvent('PLAYER_LOGOUT'); E:InitDB(); E:OnEvent('PLAYER_ENTERING_WORLD',false,true); assert(E.db.session.state=='paused')")
test('Reload preserves stop', "E:Start(); loot(1,1); E:Finish(); E:OnEvent('PLAYER_LOGOUT'); E:InitDB(); E:OnEvent('PLAYER_ENTERING_WORLD',false,true); assert(E.db.session.state=='finished')")
test('Skinning fallback counts confirmed bag gain without chat', "E:Start(); lootSlots={{id=1,qty=3}}; E:OnEvent('LOOT_READY'); E:OnEvent('LOOT_OPENED'); bags={{itemID=1,stackCount=3}}; E:OnEvent('BAG_UPDATE_DELAYED'); assert(E.db.session.count==3); E:OnEvent('LOOT_CLOSED'); assert(E.db.session.count==3)")
test('Chat then bag confirmation credits once', "E:Start(); lootSlots={{id=1,qty=2}}; E:OnEvent('LOOT_READY'); loot(1,2,1); bags={{itemID=1,stackCount=2}}; E:OnEvent('BAG_UPDATE_DELAYED'); assert(E.db.session.count==2)")
test('Bag confirmation then chat credits once', "E:Start(); lootSlots={{id=1,qty=2}}; E:OnEvent('LOOT_READY'); bags={{itemID=1,stackCount=2}}; E:OnEvent('BAG_UPDATE_DELAYED'); loot(1,2,1); assert(E.db.session.count==2)")
test('Loot window alone never credits another player or full bags', "E:Start(); lootSlots={{id=1,qty=2}}; E:OnEvent('LOOT_READY'); E:OnEvent('LOOT_CLOSED'); E:OnEvent('BAG_UPDATE_DELAYED'); assert(E.db.session.count==0)")
test('Unrelated bag additions have no loot provenance', "E:Start(); bags={{itemID=1,stackCount=50}}; E:OnEvent('BAG_UPDATE_DELAYED'); assert(E.db.session.count==0)")
test('Late bag update after loot closes', "E:Start(); lootSlots={{id=1,qty=1}}; E:OnEvent('LOOT_READY'); E:OnEvent('LOOT_CLOSED'); bags={{itemID=1,stackCount=1}}; E:OnEvent('BAG_UPDATE_DELAYED'); assert(E.db.session.count==1)")
test('Fallback cannot exceed the observed loot quantity', "E:Start(); lootSlots={{id=1,qty=1}}; E:OnEvent('LOOT_READY'); bags={{itemID=1,stackCount=50}}; E:OnEvent('BAG_UPDATE_DELAYED'); assert(E.db.session.count==1)")
test('Paused loot cannot backfill after resume', "E:Start(); lootSlots={{id=1,qty=1}}; E:OnEvent('LOOT_READY'); E:Pause(); bags={{itemID=1,stackCount=1}}; E:Start(); E:OnEvent('BAG_UPDATE_DELAYED'); assert(E.db.session.count==0)")
test('Auto pricing defaults to TSM before Auctionator', "assert(E.db.pricing=='auto'); TSM_API={GetCustomPriceValue=function() return 12001 end}; Auctionator={API={v1={GetAuctionPriceByItemID=function() return 999 end}}}; E:Start(); loot(1,2); local r=E.db.session.items['item:1:0']; assert(r.source=='TSM' and r.unit==12001 and E:Totals(E.db.session)==24002)")
test('Auctionator used when TSM has no data', "TSM_API={GetCustomPriceValue=function() return nil end}; Auctionator={API={v1={GetAuctionPriceByItemID=function() return 1002 end}}}; E:Start(); loot(1,1); local r=E.db.session.items['item:1:0']; assert(r.source=='Auctionator' and r.unit==1002)")
test('Provider errors and invalid prices fall back to vendor', "TSM_API={GetCustomPriceValue=function() error('not ready') end}; Auctionator={API={v1={GetAuctionPriceByItemID=function() return 0/0 end}}}; E:Start(); loot(1,1); assert(E.db.session.items['item:1:0'].source=='Vendor')")
test('Manual price overrides market and clearing restores auto', "TSM_API={GetCustomPriceValue=function() return 10 end}; E:Start(); loot(1,1); E:SetPrice(1,50); assert(E:Totals(E.db.session)==50); E:SetPrice(1,nil); assert(E:Totals(E.db.session)==10)")
test('Explicit provider selection respects choice', "E.db.pricing='auctionator'; TSM_API={GetCustomPriceValue=function() return 100 end}; E:Start(); loot(1,1); assert(E.db.session.items['item:1:0'].source=='Vendor'); E.db.pricing='vendor'; E:RepriceSession(); assert(E:Totals(E.db.session)==7)")
